hammingNorm_smul_le_hammingNorm.thmStatement:
∀ {α : Type u_1} {ι : Type u_2} {β : ι → Type u_3} [inst : Fintype ι] [inst_1 : (i : ι) → DecidableEq (β i)]
  [inst_2 : (i : ι) → Zero (β i)] [inst_3 : Zero α] [inst_4 : (i : ι) → SMulWithZero α (β i)] {k : α}
  {x : (i : ι) → β i}, hammingNorm (k • x) ≤ hammingNorm x

hammingNorm.congr_simp.thmStatement:
∀ {ι : Type u_2} {β : ι → Type u_3} [inst : Fintype ι] {inst_1 : (i : ι) → DecidableEq (β i)}
  [inst_2 : (i : ι) → DecidableEq (β i)] [inst_3 : (i : ι) → Zero (β i)] (x x_1 : (i : ι) → β i),
  x = x_1 → hammingNorm x = hammingNorm x_1

hammingDist_comp_le_hammingDist.thmStatement:
∀ {ι : Type u_2} {β : ι → Type u_3} [inst : Fintype ι] [inst_1 : (i : ι) → DecidableEq (β i)] {γ : ι → Type u_4}
  [inst_2 : (i : ι) → DecidableEq (γ i)] (f : (i : ι) → γ i → β i) {x y : (i : ι) → γ i},
  (hammingDist (fun i => f i (x i)) fun i => f i (y i)) ≤ hammingDist x y

hammingDist_comp.thmStatement:
∀ {ι : Type u_2} {β : ι → Type u_3} [inst : Fintype ι] [inst_1 : (i : ι) → DecidableEq (β i)] {γ : ι → Type u_4}
  [inst_2 : (i : ι) → DecidableEq (γ i)] (f : (i : ι) → γ i → β i) {x y : (i : ι) → γ i},
  (∀ (i : ι), Function.Injective (f i)) → (hammingDist (fun i => f i (x i)) fun i => f i (y i)) = hammingDist x y

hammingDist.congr_simp.thmStatement:
∀ {ι : Type u_2} {β : ι → Type u_3} [inst : Fintype ι] {inst_1 : (i : ι) → DecidableEq (β i)}
  [inst_2 : (i : ι) → DecidableEq (β i)] (x x_1 : (i : ι) → β i),
  x = x_1 → ∀ (y y_1 : (i : ι) → β i), y = y_1 → hammingDist x y = hammingDist x_1 y_1

CategoryTheory.Sigma.natTrans_app.thmStatement:
∀ {I : Type w₁} {C : I → Type u₁} [inst : (i : I) → CategoryTheory.Category.{v₁, u₁} (C i)] {D : Type u₂}
  [inst_1 : CategoryTheory.Category.{v₂, u₂} D] {F G : CategoryTheory.Functor ((i : I) × C i) D}
  (h : (i : I) → (CategoryTheory.Sigma.incl i).comp F ⟶ (CategoryTheory.Sigma.incl i).comp G) (i : I) (X : C i),
  (CategoryTheory.Sigma.natTrans h).app ⟨i, X⟩ = (h i).app X

CategoryTheory.Sigma.natIso_inv.thmStatement:
∀ {I : Type w₁} {C : I → Type u₁} [inst : (i : I) → CategoryTheory.Category.{v₁, u₁} (C i)] {D : Type u₂}
  [inst_1 : CategoryTheory.Category.{v₂, u₂} D] {q₁ q₂ : CategoryTheory.Functor ((i : I) × C i) D}
  (h : (i : I) → (CategoryTheory.Sigma.incl i).comp q₁ ≅ (CategoryTheory.Sigma.incl i).comp q₂),
  (CategoryTheory.Sigma.natIso h).inv = CategoryTheory.Sigma.natTrans fun i => (h i).inv

CategoryTheory.Sigma.natIso_hom.thmStatement:
∀ {I : Type w₁} {C : I → Type u₁} [inst : (i : I) → CategoryTheory.Category.{v₁, u₁} (C i)] {D : Type u₂}
  [inst_1 : CategoryTheory.Category.{v₂, u₂} D] {q₁ q₂ : CategoryTheory.Functor ((i : I) × C i) D}
  (h : (i : I) → (CategoryTheory.Sigma.incl i).comp q₁ ≅ (CategoryTheory.Sigma.incl i).comp q₂),
  (CategoryTheory.Sigma.natIso h).hom = CategoryTheory.Sigma.natTrans fun i => (h i).hom

CategoryTheory.Sigma.mapComp_inv_app.thmStatement:
∀ {I : Type w₁} (C : I → Type u₁) [inst : (i : I) → CategoryTheory.Category.{v₁, u₁} (C i)] {J : Type w₂} {K : Type w₃}
  (f : K → J) (g : J → I) (X : (i : K) × (fun i => C (g (f i))) i),
  (CategoryTheory.Sigma.mapComp C f g).inv.app X = CategoryTheory.CategoryStruct.id ⟨g (f X.fst), X.snd⟩

CategoryTheory.Sigma.mapComp_hom_app.thmStatement:
∀ {I : Type w₁} (C : I → Type u₁) [inst : (i : I) → CategoryTheory.Category.{v₁, u₁} (C i)] {J : Type w₂} {K : Type w₃}
  (f : K → J) (g : J → I) (X : (i : K) × (fun i => C (g (f i))) i),
  (CategoryTheory.Sigma.mapComp C f g).hom.app X = CategoryTheory.CategoryStruct.id ⟨g (f X.fst), X.snd⟩

CategoryTheory.Sigma.desc_obj.thmStatement:
∀ {I : Type w₁} {C : I → Type u₁} [inst : (i : I) → CategoryTheory.Category.{v₁, u₁} (C i)] {D : Type u₂}
  [inst_1 : CategoryTheory.Category.{v₂, u₂} D] (F : (i : I) → CategoryTheory.Functor (C i) D) (X : (i : I) × C i),
  (CategoryTheory.Sigma.desc F).obj X = (F X.fst).obj X.snd

CategoryTheory.Sigma.desc_map_mk.thmStatement:
∀ {I : Type w₁} {C : I → Type u₁} [inst : (i : I) → CategoryTheory.Category.{v₁, u₁} (C i)] {D : Type u₂}
  [inst_1 : CategoryTheory.Category.{v₂, u₂} D] (F : (i : I) → CategoryTheory.Functor (C i) D) {i : I} (X Y : C i)
  (f : X ⟶ Y), (CategoryTheory.Sigma.desc F).map (CategoryTheory.Sigma.SigmaHom.mk f) = (F i).map f
